#include <cstddef>
#include <queue>
#include <string>
#include <vector>

struct Job
{
    std::string name{};
    int priority{};
};

std::vector<std::string> printOrder(const std::vector<Job>& jobs)
{
    struct Entry
    {
        int priority{};
        std::size_t position{};
    };
    // "less" for the queue: a is printed AFTER b when it is less urgent, or equally urgent but later.
    const auto later{ [](const Entry& a, const Entry& b)
    {
        if (a.priority != b.priority)
        {
            return a.priority < b.priority;
        }
        return a.position > b.position;
    } };

    std::priority_queue<Entry, std::vector<Entry>, decltype(later)> queue{ later };
    for (std::size_t i{ 0 }; i < jobs.size(); ++i)
    {
        queue.push(Entry{ jobs[i].priority, i });
    }

    std::vector<std::string> order{};
    while (!queue.empty())
    {
        order.push_back(jobs[queue.top().position].name);
        queue.pop();
    }
    return order;
}

unitTests:
using Names = std::vector<std::string>;
TEST("urgent jobs jump the queue") { CHECK_EQ(printOrder({ { "report", 3 }, { "ticket", 9 }, { "photo", 1 } }), (Names{ "ticket", "report", "photo" })); }
TEST("equal priorities keep submission order") { CHECK_EQ(printOrder({ { "a", 5 }, { "b", 5 }, { "c", 5 }, { "d", 5 } }), (Names{ "a", "b", "c", "d" })); }
TEST("mixed") { CHECK_EQ(printOrder({ { "a", 2 }, { "b", 7 }, { "c", 2 }, { "d", 7 }, { "e", 9 }, { "f", 2 } }), (Names{ "e", "b", "d", "a", "c", "f" })); }
TEST("nothing to print") { CHECK(printOrder({}).empty()); }

